{
  "groups": [
    {
      "group_id": "vulnerable_variable_rate",
      "rule": "rate_type == 'variable' and mortgage_rate_pct > 5.0",
      "rationale": "Borrowers with variable rates at high interest levels are likely to be sensitive to payment shocks and actively considering refinancing."
    },
    {
      "group_id": "high_balance_recent_originators",
      "rule": "origination_year >= 2022 and mortgage_balance_cad > 420000",
      "rationale": "Recent mortgage originations with high debt loads are often the most price-sensitive segments when facing renewal."
    },
    {
      "group_id": "equity_rich_stable_tenure",
      "rule": "td_tenure_months > 80 and credit_score_band == '720_plus'",
      "rationale": "Long-tenure, high-credit borrowers have significant equity and market options, making them prime targets for competitive retention offers."
    },
    {
      "group_id": "stressed_renters_and_investors",
      "rule": "occupancy_type != 'owner_occupied' and credit_utilization_pct > 40",
      "rationale": "Non-owner-occupied properties with high credit utilization indicate potential cash-flow strain and higher churn risk."
    },
    {
      "group_id": "low_income_large_families",
      "rule": "household_income_cad < 75000 and n_children >= 3",
      "rationale": "Large households with lower income have limited budget flexibility and are highly motivated by payment reductions."
    },
    {
      "group_id": "mature_fixed_rate_holders",
      "rule": "rate_type == 'fixed' and origination_year <= 2019",
      "rationale": "Borrowers nearing the end of long-term fixed contracts established years ago will face significant payment increases at renewal."
    },
    {
      "group_id": "life_event_driven_switchers",
      "rule": "life_event_6m == True",
      "rationale": "Recent life changes like job shifts or relocations typically trigger a re-evaluation of mortgage arrangements and banking relationships."
    },
    {
      "group_id": "retired_conservative_savers",
      "rule": "employment_status == 'retired' and has_savings == True",
      "rationale": "Retired borrowers with liquid assets are often less sensitive to rate fluctuations and prioritize product stability over lowest price."
    }
  ]
}
